package com.theemeraldpig.blobsplit;

import android.app.AlertDialog;
import android.content.Context;
import android.util.AttributeSet;
import android.util.Log;

import com.theemeraldpig.blobsplit.mobile.EbitenView;

// The game view generated by ebitenmobile. If the game stops with an error, show it
// instead of leaving a black screen.
public class GameView extends EbitenView {
    private boolean shown;

    public GameView(Context context) { super(context); }
    public GameView(Context context, AttributeSet attrs) { super(context, attrs); }

    @Override
    protected void onErrorOnGameUpdate(Exception e) {
        Log.e("BlobSplit", "game stopped", e);
        if (shown) return;
        shown = true;
        try {
            new AlertDialog.Builder(getContext())
                .setTitle("Blob Split ran into a problem")
                .setMessage(String.valueOf(e))
                .setPositiveButton("OK", null)
                .show();
        } catch (Exception ignored) {
        }
    }
}
